function audFor(partId){ return AUDIO.filter(a => a.part === partId); }


function matsFor(partId){ return MATERIALS.filter(m => m.part === partId); }
function lecsFor(partId){ return LECTURES.filter(l => l.part === partId); }
function fmtDur(s){ const m = Math.floor(s/60); return m + ' min'; }
function fmtTime(s){ return String(Math.floor(s/60)).padStart(2,'0') + ':' + String(s%60).padStart(2,'0'); }
